    /**
     * Tests getting all DeviceModels.
     *
     * @return    Collection
     */
    public List<DeviceModel> testGetAll() throws Throwable {
    LOGGER.info( "DeviceModelTest:testGetAll() - Retrieving Collection of DeviceModels:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DeviceModel : " );
    List<DeviceModel> collection  = null;

    try {
        // call the static get method on the DeviceModelService
        collection = service.getAllDeviceModel();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DeviceModel currEntity  = null;
            Iterator<DeviceModel> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDeviceModelId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

